import AppKit
import CryptoKit
import ImageIO

@MainActor
public class ClipboardMonitor: NSObject {
    public static let shared = ClipboardMonitor()
    
    private var timer: Timer?
    private var lastChangeCount: Int = 0
    private let pasteboard = NSPasteboard.general
    
    // Concealed types from password managers & PasteFlow Vault auto-clear
    private let concealedTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType"
    ]
    
    private override init() {
        super.init()
        lastChangeCount = pasteboard.changeCount
    }
    
    public func startMonitoring() {
        stopMonitoring()
        lastChangeCount = pasteboard.changeCount
        
        // Direct RunLoop selector timer with 100ms coalescing tolerance: ZERO heap allocations when idle
        let newTimer = Timer(
            timeInterval: 0.35,
            target: self,
            selector: #selector(timerFired),
            userInfo: nil,
            repeats: true
        )
        newTimer.tolerance = 0.1
        RunLoop.main.add(newTimer, forMode: .common)
        self.timer = newTimer
    }
    
    public func stopMonitoring() {
        timer?.invalidate()
        timer = nil
    }
    
    @objc private func timerFired() {
        guard !HistoryStore.shared.isMonitoringPaused else { return }
        let currentCount = pasteboard.changeCount
        guard currentCount != lastChangeCount else { return }
        lastChangeCount = currentCount
        processPasteboard()
    }
    
    private func processPasteboard() {
        guard let items = pasteboard.pasteboardItems, !items.isEmpty else { return }
        
        // 1. Check concealed / password manager / self-paste flags
        for pbItem in items {
            for type in pbItem.types {
                if concealedTypes.contains(type.rawValue) {
                    return
                }
            }
        }
        
        // 2. Identify frontmost source application
        let frontApp = NSWorkspace.shared.frontmostApplication
        let appName = frontApp?.localizedName
        let appBundleID = frontApp?.bundleIdentifier
        
        if let bundleID = appBundleID, HistoryStore.shared.ignoredBundleIDs.contains(bundleID) {
            return
        }
        
        // 3. Check for File URLs
        if let fileURLs = pasteboard.readObjects(forClasses: [NSURL.self], options: nil) as? [URL], !fileURLs.isEmpty {
            let paths = fileURLs.map { $0.path }
            let isSingleImage = (paths.count == 1 && ["png", "jpg", "jpeg", "gif", "webp", "tiff", "heic"].contains(fileURLs[0].pathExtension.lowercased()))
            
            if !isSingleImage {
                let checksum = computeSHA256(data: Data(paths.joined(separator: "|").utf8))
                let item = ClipboardItem(
                    contentType: .file,
                    textValue: paths.joined(separator: "\n"),
                    filePaths: paths,
                    appBundleID: appBundleID,
                    appName: appName,
                    checksum: checksum
                )
                
                HistoryStore.shared.addItem(item)
                SoundManager.shared.playCopy()
                return
            }
        }
        
        // 4. PNG Fast-Path & Image capture without uncompressed TIFF bloat when PNG is already on pasteboard
        if let directPNG = pasteboard.data(forType: .png) {
            var width: Int? = nil
            var height: Int? = nil
            if let src = CGImageSourceCreateWithData(directPNG as CFData, nil),
               let props = CGImageSourceCopyPropertiesAtIndex(src, 0, nil) as? [CFString: Any] {
                width = props[kCGImagePropertyPixelWidth] as? Int
                height = props[kCGImagePropertyPixelHeight] as? Int
            }
            let checksum = computeSHA256(data: directPNG)
            if let saved = HistoryStore.shared.saveImageWithThumbnail(data: directPNG) {
                let item = ClipboardItem(
                    contentType: .image,
                    imageFileName: saved.fileName,
                    thumbnailFileName: saved.thumbFileName,
                    imageWidth: width,
                    imageHeight: height,
                    appBundleID: appBundleID,
                    appName: appName,
                    checksum: checksum
                )
                HistoryStore.shared.addItem(item)
                SoundManager.shared.playCopy()
            }
            return
        } else if let tiff = pasteboard.data(forType: .tiff),
                  let bitmap = NSBitmapImageRep(data: tiff),
                  let pngData = bitmap.representation(using: .png, properties: [:]) {
            let checksum = computeSHA256(data: pngData)
            if let saved = HistoryStore.shared.saveImageWithThumbnail(data: pngData) {
                let item = ClipboardItem(
                    contentType: .image,
                    imageFileName: saved.fileName,
                    thumbnailFileName: saved.thumbFileName,
                    imageWidth: bitmap.pixelsWide,
                    imageHeight: bitmap.pixelsHigh,
                    appBundleID: appBundleID,
                    appName: appName,
                    checksum: checksum
                )
                HistoryStore.shared.addItem(item)
                SoundManager.shared.playCopy()
            }
            return
        }
        
        // 5. Check for Plain Text & Rich Text (skip unused HTML & oversized RTF > 8 KB to prevent RAM bloat)
        if let string = pasteboard.string(forType: .string), !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let rawRtf = pasteboard.data(forType: .rtf)
            let rtfData = (rawRtf != nil && rawRtf!.count <= 8192) ? rawRtf : nil
            
            let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
            let detectedType = classifyTextContent(string)
            let storedText = (detectedType == .color || detectedType == .link) ? trimmed : string
            let checksum = computeSHA256(data: Data(storedText.utf8))
            
            let item = ClipboardItem(
                contentType: detectedType,
                textValue: storedText,
                rtfData: rtfData,
                htmlData: nil,
                appBundleID: appBundleID,
                appName: appName,
                checksum: checksum
            )
            
            HistoryStore.shared.addItem(item)
            SoundManager.shared.playCopy()
        }
    }
    
    private func classifyTextContent(_ text: String) -> ContentType {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        
        if trimmed.hasPrefix("#") {
            let count = trimmed.count
            if count == 4 || count == 7 || count == 9 {
                if trimmed.dropFirst().allSatisfy({ $0.isHexDigit }) {
                    return .color
                }
            }
        } else if trimmed.hasPrefix("rgb(") || trimmed.hasPrefix("rgba(") || trimmed.hasPrefix("hsl(") || trimmed.hasPrefix("hsla(") {
            if trimmed.hasSuffix(")") {
                return .color
            }
        }
        
        if (trimmed.hasPrefix("http://") || trimmed.hasPrefix("https://") || trimmed.hasPrefix("ftp://")),
           !trimmed.contains(" "),
           !trimmed.contains("\n"),
           URL(string: trimmed) != nil {
            return .link
        }
        
        let codeIndicators = [
            "func ", "import ", "class ", "struct ", "let ", "var ", "const ",
            "def ", "return ", "if (", "for (", "public ", "private ", "async ",
            "await ", "=>", "->", "println", "console.log", "#include", "SELECT ", "FROM "
        ]
        var newlineCount = 0
        for scalar in text.unicodeScalars {
            if scalar == "\n" {
                newlineCount += 1
                if newlineCount > 3 { break }
            }
        }
        let isMultiline = newlineCount > 3
        let hasBraces = text.contains("{") && text.contains("}")
        
        var codeScore = 0
        if hasBraces && isMultiline { codeScore += 2 }
        if codeScore >= 2 { return .code }
        for indicator in codeIndicators {
            if text.contains(indicator) {
                codeScore += 1
                if codeScore >= 2 { return .code }
            }
        }
        return .text
    }
    
    private static let hexDigits = Array("0123456789abcdef".utf8)
    
    private func computeSHA256(data: Data) -> String {
        let digest = SHA256.hash(data: data)
        var bytes = [UInt8]()
        bytes.reserveCapacity(64)
        for byte in digest {
            bytes.append(Self.hexDigits[Int(byte >> 4)])
            bytes.append(Self.hexDigits[Int(byte & 0x0F)])
        }
        return String(decoding: bytes, as: UTF8.self)
    }
}
